 for(const key of ['modelCalls','judgeCalls','genuineCredit'])assert.equal(r[key],0);
 assert.equal(r.actualModelProof,false);assert.equal(r.installedWrites,false);assert.deepEqual(r.requests,{browser:0,api:0});
