async function builderBrowserApi(page,args,timeoutMs=120000){
 assert(Number.isInteger(timeoutMs)&&timeoutMs>0&&timeoutMs<=120000);const id=crypto.randomUUID();
 await page.evaluate(({id,args})=>{const calls=globalThis.__xssBuilderQualificationApiCalls ||= new Map();if(calls.size)throw Error('Concurrent builder API request denied');const controller=new AbortController(),state={done:false,controller};calls.set(id,state);fetch(args.url,{method:args.method,headers:{Authorization:'Bearer '+args.token,'Content-Type':'application/json'},signal:controller.signal,...(args.body===undefined?{}:{body:JSON.stringify(args.body)})}).then(async response=>{const text=await response.text();let body;try{body=JSON.parse(text);}catch{body=text;}state.result={status:response.status,body,csp:response.headers.get('content-security-policy')};}).catch(error=>{state.error={name:error.name,message:error.message};}).finally(()=>{state.done=true;});},{id,args});
 try{const deadline=Date.now()+timeoutMs;let result;for(;;){assert(Date.now()<deadline,'Builder API completion timeout');result=await page.evaluate(id=>{const state=globalThis.__xssBuilderQualificationApiCalls.get(id);return {done:state.done,result:state.result||null,error:state.error||null};},id);if(result.done)break;await new Promise(resolve=>setTimeout(resolve,Math.min(50,Math.max(1,deadline-Date.now()))));}if(result.error)throw Object.assign(new Error(result.error.message),{name:result.error.name});return result.result;}
 finally{await page.evaluate(id=>{const calls=globalThis.__xssBuilderQualificationApiCalls,state=calls?.get(id);if(state&&!state.done)state.controller.abort();calls?.delete(id);},id);}
}
