function assertBuilderActualReceipt(r){const p=require('./xssReflectedActualWirePolicy').builderConfiguration();assert.equal(r.profile,p.PROFILE);assert.equal(r.status,'passed');assert.deepEqual(r.cases.map(x=>x.caseId),p.CASES.map(x=>x.id));assert(r.cases.every(x=>x.status==='verified'));for(const c of r.cases.filter(x=>x.positive))for(const key of ['learnerContent','adminPreview','independentGates','completedProjection'])assert.equal(c[key],true);for(const key of ['actualModelProof','wireBinding','masterGates','dashboardParity','adminProgress','sessionDenied','foreignDenied','resetRetired','resetReplay','resetTimeCleared','resetReplayExact','immutableEvidencePreserved','profilePreserved','siblingPreserved','configurationRestored'])assert.equal(r[key],true);assert.equal(r.genuineCredit,4);assert.equal(r.controlledProjectionCount,0);assert.equal(r.installedWrites,false);assert(r.modelCalls>=15&&r.modelCalls<=25);assert(r.judgeCalls>=5&&r.judgeCalls<=10);assert.deepEqual(r.cleanupFailures,[]);assert(r.cleanup.length&&r.cleanup.every(x=>x.status==='fulfilled'));for(const key of ['browser','api'])assert(r.requests[key]>0&&r.requests[key]<=LIMITS[key]);}
